import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const m=JSON.parse('{"title":"Common errors — the high-frequency list","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/common-errors.md","filePath":"troubleshooting/common-errors.md"}'),a={name:"troubleshooting/common-errors.md"};function s(c,t,i,n,l,h){return d(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="common-errors-—-the-high-frequency-list" tabindex="-1">Common errors — the high-frequency list <a class="header-anchor" href="#common-errors-—-the-high-frequency-list" aria-label="Permalink to &quot;Common errors — the high-frequency list&quot;">​</a></h1><p>The errors you will actually hit, most-frequent first, each as <strong>symptom → cause → fix</strong>. This is the short list; the complete per-subsystem inventory (with investigation chains) is <a href="./error-catalog.html">error-catalog.md</a>; failures that print nothing are <a href="./silent-failures.html">silent-failures.md</a>.</p><h2 id="log-and-watchdog-errors" tabindex="-1">Log and watchdog errors <a class="header-anchor" href="#log-and-watchdog-errors" aria-label="Permalink to &quot;Log and watchdog errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>logcat: bad level (debug/info/warn/error/fatal or 0-4)</code></td><td>wrong level spelling</td><td><code>logcat -l warn</code> or <code>-l 2</code></td></tr><tr><td><code>klog: flush FAILED (no filesystem mounted?)</code> (rotate/export twins)</td><td>/var/log not backed by a volume</td><td>mount one; <code>logctl flush</code> then writes <code>/var/log/kernel.log</code></td></tr><tr><td><code>logctl: bad level (&#39;-&#39; = any)</code></td><td>filter syntax</td><td><code>logctl filter &lt;clear|[level] [module] [keyword]&gt;</code></td></tr><tr><td>dmesg footer says <code>dropped &lt;N&gt;</code></td><td>the 1024-entry ring wrapped</td><td><code>dmesg 1024</code>; consider <code>logctl threshold</code> + <code>flush</code></td></tr><tr><td>a message you expected never appears</td><td>level disabled or filter active</td><td><code>logctl status</code>; <code>logctl test</code> calibrates the pipeline (5 lines, module <code>klogtest</code>)</td></tr><tr><td><code>watchdog: register FAILED (table full?)</code></td><td>8 slots max</td><td><code>watchdog slots</code>; stop one first</td></tr><tr><td><code>watchdog hw: start FAILED (bad timeout?)</code></td><td>TCO range is 2..63 s</td><td><code>watchdog hw start 30</code></td></tr><tr><td><code>watchdog hw: feed FAILED (not armed?)</code></td><td>feed before start</td><td><code>watchdog hw start</code> first</td></tr><tr><td><code>health: export FAILED (no filesystem mounted?)</code></td><td>export target missing</td><td>mount a volume; <code>health export /mnt/health.txt</code></td></tr></tbody></table><h2 id="tui-and-display-errors" tabindex="-1">TUI and display errors <a class="header-anchor" href="#tui-and-display-errors" aria-label="Permalink to &quot;TUI and display errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>tui</code> pages print nothing through scripts</td><td>TUI ops route DIRECT, bypassing capture</td><td>run <code>tui</code> interactively; only <code>tui-test</code> serves text through capture</td></tr><tr><td><code>page &#39;%s&#39; failed (rc=%d)</code> / <code>tui: desktop init failed</code></td><td>desktop internals</td><td><code>dmesg 100</code>; report with serial capture</td></tr><tr><td><code>value out of range (1980-2099, ...)</code> (time page)</td><td>RTC set guards</td><td>set a valid date</td></tr><tr><td><code>volume: device rejected the level</code> (hw page)</td><td>mixer clamp</td><td>use 0-100</td></tr><tr><td>editor <code>[save failed]</code></td><td>read-only fs or partial buffer</td><td>check <code>mounts</code>; <code>[PARTIAL: save refused]</code> = over-limit file</td></tr><tr><td>Chinese shows as keys or tofu</td><td>locale/encoding mismatch</td><td><code>lang zh</code>, <code>serial_encoding utf8</code> (match your terminal)</td></tr></tbody></table><h2 id="ocse-installer-errors-from-the-install-medium" tabindex="-1">OCSE installer errors (from the install medium) <a class="header-anchor" href="#ocse-installer-errors-from-the-install-medium" aria-label="Permalink to &quot;OCSE installer errors (from the install medium)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>ocblmbr.bin MISSING</code> / <code>ocos.tar MISSING</code></td><td>incomplete medium</td><td>re-download the ISO; verify size/SHA</td></tr><tr><td><code>install: FATAL - extraction failed</code></td><td>ocos.tar corrupt</td><td>same</td></tr><tr><td><code>mkpart failed</code> / <code>created partition not found</code></td><td>target disk problems</td><td>run the disk checks first; try another disk</td></tr><tr><td><code>install: FATAL - could not set the boot flag</code></td><td>partition table write failed</td><td>re-run; check the medium</td></tr><tr><td>installer settings ignored after install</td><td>BUG-129 config dialect split</td><td>set keys again from the running system: <code>config set shell.lang zh</code></td></tr><tr><td>OCSE GUI clicks do nothing</td><td>BUG-113</td><td>CLI hotkey Ctrl+Alt+F2, or the <code>click &lt;x&gt; &lt;y&gt;</code> command</td></tr></tbody></table><h2 id="power-errors" tabindex="-1">Power errors <a class="header-anchor" href="#power-errors" aria-label="Permalink to &quot;Power errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Suspend not supported (ACPI required).</code></td><td>no ACPI tables on the machine</td><td>expected on some VMs/old boards</td></tr><tr><td><code>S3 resume failed.</code></td><td>resume path broken</td><td>report; data loss risk — save first</td></tr><tr><td><code>System halted.</code> and nothing else</td><td>that IS the halt success message</td><td>power off at the host</td></tr></tbody></table><h2 id="recovery-environment-ocire-errors" tabindex="-1">Recovery environment (OCIRE) errors <a class="header-anchor" href="#recovery-environment-ocire-errors" aria-label="Permalink to &quot;Recovery environment (OCIRE) errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Supervisor: no OCIRE recovery volume found</code></td><td>the hd1 0xEE+FAT12 volume is absent</td><td>re-install with the recovery partition (OCSE creates it)</td></tr><tr><td><code>logread: BAD ring header (magic/cursor)</code></td><td>boot-log ring corrupt</td><td><code>repair quick</code> resets it</td></tr><tr><td><code>WARNING: log agent digest mismatch</code></td><td>agent image vs mailbox digest differ (tamper guard)</td><td><code>syscheck</code>, then <code>repair</code></td></tr><tr><td><code>REBUILD FAILED</code> / <code>RESET FAILED</code> during repair</td><td>golden set or medium damage</td><td>re-run; another golden set</td></tr><tr><td><code>Unknown command: &lt;cmd&gt;</code> in <code>oc&gt;</code></td><td>the recovery shell is tiny</td><td><code>help</code> lists it; hidden extra: <code>lang [en|zh]</code></td></tr></tbody></table><h2 id="the-universal-first-moves" tabindex="-1">The universal first moves <a class="header-anchor" href="#the-universal-first-moves" aria-label="Permalink to &quot;The universal first moves&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; health          # alarms: memory &gt;90%, tasks &gt;64, CPU &gt;=90%x10s</span></span>
<span class="line"><span>ush&gt; dmesg 100       # the kernel log tail (ring 1024)</span></span>
<span class="line"><span>ush&gt; crashlog        # panics you may not have seen (32-slot ring)</span></span></code></pre></div><hr><h2 id="shell-and-file-tools" tabindex="-1">Shell and file tools <a class="header-anchor" href="#shell-and-file-tools" aria-label="Permalink to &quot;Shell and file tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>ush: command not found: &lt;cmd&gt;</code></td><td>typo, or the program is not in the registry</td><td><code>help -a</code> (or <code>help -w</code> for grouped); check <a href="./../manual/function-dictionary.html">../manual/function-dictionary.md</a></td></tr><tr><td><code>ush: syntax error near &#39;&gt;&#39;</code> (or <code>&#39;&lt;&#39;</code>)</td><td>empty redirect target</td><td>name the file: <code>cmd &gt; file</code></td></tr><tr><td><code>ush: &#39;exit&#39; is not available; ...</code></td><td>by design — ush is the boot entry</td><td><code>shutdown</code> / <code>reboot</code></td></tr><tr><td><code>ush: job control requires external programs</code></td><td><code>fg</code>/<code>bg</code> are recognized but not implemented</td><td>use <code>jobs</code> to list; there is no resume</td></tr><tr><td><code>cat: cannot open &lt;path&gt;</code> (also head/tail/sort/uniq/wc/awk)</td><td>sys_open failed: missing file, wrong cwd</td><td><code>pwd</code>, <code>ls</code>; paths are relative to the shell cwd</td></tr><tr><td><code>mkdir: cannot create &#39;&lt;path&gt;&#39;</code></td><td>exists, or parent missing</td><td>create parents first</td></tr><tr><td><code>rm: cannot remove &#39;&lt;path&gt;&#39;</code> / <code>rmdir: ...</code></td><td>file busy (open fd), or dir not empty</td><td>close it; <code>ls</code> the dir</td></tr><tr><td><code>ln: cannot create symlink (target must be an absolute path)</code></td><td>symlink targets are absolute-only</td><td><code>ln -s /abs/target link</code></td></tr><tr><td><code>sed: unknown script</code></td><td>only <code>s/old/new/[g]</code>, <code>-n Np</code>, <code>Nd</code> exist</td><td>see <a href="./../manual/ush-reference.html">../manual/ush-reference.md</a></td></tr><tr><td><code>awk: missing {print ...}</code></td><td>the tiny awk supports <code>{print ...}</code> only</td><td>same</td></tr><tr><td><code>help: unknown option &#39;&lt;o&gt;&#39;</code></td><td>only <code>-a</code>/<code>--all</code>, <code>-w</code>/<code>--wp</code> exist</td><td><code>help -a</code></td></tr><tr><td><code>run: unknown program: &lt;name&gt;</code></td><td>registry lookup failed</td><td><code>help -a</code>; the registry is build-frozen at 284</td></tr><tr><td><code>ls *</code> lists a file literally named <code>*</code></td><td><strong>no globbing anywhere</strong> (ush and ls)</td><td>name files explicitly</td></tr><tr><td><code>disk-tool: unknown op: &lt;op&gt;</code> (any mega-app)</td><td>the verbatim table miss</td><td>the app&#39;s <code>usage:</code> lists its table; <code>help -w</code> groups all commands</td></tr><tr><td><code>&lt;app&gt;: service call failed (rc=-1)</code> (250 apps share this)</td><td>the L1SVC bridge returned -1</td><td>re-run; <code>dmesg 100</code>; the family&#39;s <code>_test</code> stub; then <a href="./error-catalog.html">error-catalog.md</a> §7.1</td></tr><tr><td>nano/vi screen left dirty after exit</td><td>BUG-111 (editor afterimages)</td><td><code>clear</code></td></tr><tr><td>tofu blocks for Chinese on screen (serial fine)</td><td>BUG-110/130 console-fallback UTF-8</td><td>fixed in current builds; update the image</td></tr><tr><td>editor: <code>[PARTIAL: save refused]</code></td><td>file exceeds 256 lines × 128 bytes</td><td>by design (BUG-34 fix); split the file</td></tr></tbody></table><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>DHCP failed (timeout)</code></td><td>no OFFER/ACK — user-net missing, cable, or server</td><td><code>ip</code> (0.0.0.0?), then <code>dhcp</code> again; QEMU: <code>-netdev user,id=n1 -device e1000,netdev=n1</code></td></tr><tr><td><code>DNS resolution failed</code> / <code>(timeout)</code></td><td>no DNS server, or UDP blocked</td><td>re-run <code>dhcp</code> (it sets DNS); <code>dns &lt;host&gt;</code> to test; see <a href="./network-issues.html">network-issues.md</a></td></tr><tr><td><code>ping</code> prints nothing then fails</td><td>name resolution failed first (&quot;Resolving...&quot;)</td><td><code>dns &lt;host&gt;</code>; or ping the IP directly</td></tr><tr><td><code>connect failed</code></td><td>routing/firewall</td><td><code>route</code> (gateway present?), <code>firewall</code> list, <code>firewall reset</code> if experimenting</td></tr><tr><td><code>wget: cannot create file, printing to console:</code></td><td>target path unwritable</td><td>check <code>pwd</code>/mount; the body still prints to console</td></tr><tr><td><code>TLS failed (code &lt;n&gt;)</code> / <code>[tls] x509 verify failed: ... REFUSED</code></td><td>the trust decision — self-signed/unanchored chains are refused <strong>by default</strong></td><td>correct the server cert; testing-only opt-in: <code>config set tls.insecure 1</code></td></tr><tr><td><code>[ssh] HOST SIGNATURE INVALID - disconnecting</code></td><td>TOFU mismatch</td><td><code>[ssh] WARNING: HOST KEY CHANGED!</code> means the entry in <code>/etc/ssh_known_hosts</code> must be re-trusted deliberately</td></tr><tr><td><code>[ssh] USERAUTH_FAILURE — wrong password</code></td><td>credentials</td><td>defaults are user <code>oc</code> / password <code>oc</code>; publickey = password <code>-</code> with <code>/etc/ssh_client_key</code></td></tr><tr><td><code>sshd</code> refuses to start: <code>cannot obtain a per-installation host key</code></td><td>no key, keygen impossible</td><td>pre-seed <code>etc.img</code> (<code>tools/host_keygen_etc.py</code>), or free memory and retry (first boot generates in background)</td></tr><tr><td>first connect to sshd stalls</td><td>cold ARP cache after DHCP</td><td>warm it: <code>ping &lt;peer&gt;</code> first</td></tr><tr><td><code>e1000e: init failed</code> (any <code>&lt;nic&gt;: init failed</code>)</td><td>driver probe failed — card absent, BARs bad, DMA unreachable</td><td><code>lspci</code> → <code>pcidump &lt;b:d.f&gt;</code> → family status → family <code>_test</code>; template in <a href="./network-issues.html">network-issues.md</a></td></tr><tr><td><code>virtio TX timeout: avail_idx=...</code></td><td>virtio NIC stopped consuming descriptors</td><td>restart the VM/device; report if persistent</td></tr><tr><td><code>wifi scan</code> prints no networks</td><td>QEMU has no radio — honest output</td><td>real hardware, or skip</td></tr></tbody></table><h2 id="storage-and-filesystems" tabindex="-1">Storage and filesystems <a class="header-anchor" href="#storage-and-filesystems" aria-label="Permalink to &quot;Storage and filesystems&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>mount: failed</code> / <code>vfs_mount: unknown fs type</code></td><td>bad type/device/args, or the fs is not supported</td><td><code>lsblk</code>, <code>mounts</code>; types: ramfs/fat32/exfat/ext4</td></tr><tr><td><code>fat32: not a FAT32 volume (FAT12/16 detected)</code> / <code>invalid BPB</code></td><td>wrong device node, or not FAT32</td><td><code>fatstat &lt;dev&gt;</code> shows the parsed BPB; wrong node? <code>lsblk</code></td></tr><tr><td><code>ext4: unsupported INCOMP feature bits ... mount refused</code></td><td>ext4 driver is READ-ONLY with feature limits</td><td>mount a simpler ext4, or read it elsewhere</td></tr><tr><td><code>umount: target is busy - close open files first</code></td><td>open fds</td><td>close them; <code>umount: unmount nested mounts first</code> → children first (<code>mounts</code> shows nesting)</td></tr><tr><td><code>umount: cannot unmount the root filesystem</code></td><td>by design</td><td>—</td></tr><tr><td><code>fsck: not a FAT32 volume (fsck supports FAT32 only; ...)</code></td><td>fsck is FAT32-only</td><td>repair elsewhere; <code>fatstat</code> to confirm</td></tr><tr><td><code>parted: device not found</code> / <code>mkfs.*: device not found</code></td><td>bad device string</td><td><code>lsblk</code> first; names are exact</td></tr><tr><td><code>mkfs.exfat: device too small (need at least 65 sectors, got &lt;N&gt;)</code></td><td>target too small</td><td>bigger device</td></tr><tr><td><code>grub-install: MBR gap too small for &lt;N&gt;</code></td><td>post-MBR gap cannot host core.img</td><td>repartition with ≥ 1 MiB gap (or GPT)</td></tr><tr><td><code>install: disk too large for MBR (&gt;2TiB) or too small</code></td><td>MBR limits</td><td>use a ≤ 2 TiB target</td></tr><tr><td>writes lost after reboot</td><td>they lived on ramfs — only /etc and mounted volumes persist</td><td><code>mounts</code> shows what persists; <code>sync</code> before power ops</td></tr><tr><td>USB stick appears then vanishes</td><td>MSC detach path</td><td><code>usb_hotplug_test</code> reproduces; replug</td></tr><tr><td><code>blk: write to protected device ... REFUSED (ocire recovery disk)</code></td><td>whole-disk OCIRE protection (klog-only line)</td><td>by design — modify that volume only from OCIRE <code>repair</code></td></tr><tr><td>A/B disk &quot;absent&quot; right after <code>abdisk</code></td><td>service cache not yet refreshed</td><td>re-run <code>update status</code>; the wizard re-checks in a loop</td></tr><tr><td><code>blkcache: alloc FAILED - cache disabled (raw I/O)</code></td><td>cache table alloc failed; system continues uncached</td><td><code>mem</code>; report if persistent</td></tr></tbody></table><h2 id="update-ota" tabindex="-1">Update / OTA <a class="header-anchor" href="#update-ota" aria-label="Permalink to &quot;Update / OTA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>update</code> prints nothing / &quot;up to date&quot; but you expected an update</td><td>six-cause silent chain</td><td>walk <a href="./silent-failures.html">silent-failures.md</a> §7; or just run the wizard: <code>update</code> (no args)</td></tr><tr><td><code>update: cannot determine target slot (not booted from A/B?)</code></td><td>booted from ISO, no A/B layout</td><td><code>update status</code>; <code>abdisk &lt;dev&gt;</code> to create (destructive)</td></tr><tr><td><code>update: download failed: &lt;why&gt;</code></td><td>network / server</td><td>the <code>&lt;why&gt;</code> is an OC_UPDATE_E_* text — <a href="./error-codes.html">error-codes.md</a> §1</td></tr><tr><td><code>SHA256 mismatch</code> / <code>package (tar.gz) invalid</code></td><td>corrupted download</td><td>re-download; verify size</td></tr><tr><td><code>config: write rejected (empty, non-ASCII, too long, or invalid value)</code></td><td>strict value guards</td><td><code>config list</code> for shapes; ASCII values only</td></tr><tr><td><code>config: cannot read /etc/opencube.conf</code></td><td>/etc not mounted</td><td><a href="./storage-issues.html">storage-issues.md</a></td></tr></tbody></table><h2 id="kernel-boot-crash" tabindex="-1">Kernel / boot / crash <a class="header-anchor" href="#kernel-boot-crash" aria-label="Permalink to &quot;Kernel / boot / crash&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>*** KERNEL PANIC: &lt;reason&gt; ***</code></td><td>11 possible sites — the reason string names it</td><td><a href="./error-codes.html">error-codes.md</a> §panic-sites; serial is authoritative; <code>crashlog</code> after reboot</td></tr><tr><td>machine rebooted &quot;by itself&quot;</td><td>panic with policy REBOOT, or watchdog, or OCBL judged a stall</td><td><code>crashlog</code>, <code>dmesg</code>, <code>/var/log/crash.log</code>; OCBL side: <a href="./boot-failures.html">boot-failures.md</a></td></tr><tr><td>whole machine freezes, no panic (typing &#39;a&#39;/&#39;u&#39; fast, or <code>loop</code>)</td><td>BUG-109 freeze race / BUG-112 loop containment gap</td><td>capture <code>-serial file:</code> and report; avoid racing console input</td></tr><tr><td><code>[user] process table full (max &lt;N&gt; processes)</code></td><td>too many processes</td><td><code>ps</code>; <code>kill &lt;pid&gt;</code></td></tr><tr><td><code>[user] not an ELF file</code></td><td>exec target is not ELF64</td><td>expected for badapp-class fixtures; check the binary</td></tr><tr><td><code>KERNEL PANIC (no crash handler installed): &lt;reason&gt;</code></td><td>panic before the crash service registered</td><td>early-boot bug class; capture serial, report</td></tr><tr><td>boot stops at a <code>FAIL</code> stage line</td><td>that subsystem&#39;s init failed</td><td><a href="./boot-failures.html">boot-failures.md</a>; the message above the FAIL names the device</td></tr><tr><td><code>Power off not supported. System halted.</code></td><td>all power ports exhausted (VM)</td><td>use the host&#39;s power control</td></tr><tr><td><code>sleep: invalid time</code></td><td>non-numeric/negative argument</td><td><code>sleep 2</code>, <code>sleep 0.5</code></td></tr></tbody></table><h2 id="audio-usb-misc-hardware" tabindex="-1">Audio / USB / misc hardware <a class="header-anchor" href="#audio-usb-misc-hardware" aria-label="Permalink to &quot;Audio / USB / misc hardware&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>play: device error</code> / <code>: unknown device &#39;&lt;name&gt;&#39;</code></td><td>no such audio device</td><td><code>sound</code> lists registered devices</td></tr><tr><td><code>[audio_rw_test] no sound cards registered =&gt; SKIPPED</code></td><td>no audio device attached</td><td>QEMU: <code>-device intel-hda</code>; honest skip otherwise</td></tr><tr><td>QEMU hda freezes at 44.1 kHz</td><td>QEMU-10 model dead-loop (documented in-source)</td><td>real hardware is fine; other rates work</td></tr><tr><td><code>usb: SET_ADDRESS failed</code> / <code>GET_DESCRIPTOR(...) failed</code></td><td>device did not enumerate</td><td>replug; <code>usb</code>, then <code>usb_storage_test</code></td></tr><tr><td><code>virtio-blk: write rejected (device is read-only)</code></td><td>the QEMU drive is readonly=on</td><td>by design; drop the flag</td></tr><tr><td><code>no hardware watchdog present</code> lines</td><td>no WDAT/TCO — probe honesty</td><td>q35 has TCO; default pc does not</td></tr><tr><td><code>msitest: FAIL</code> while self-IPI passed</td><td>MSI routing broken</td><td><code>pcibars</code>, <code>pcie</code>, report</td></tr><tr><td><code>date: ms since boot (no RTC driver)</code></td><td>no CMOS RTC (VM default)</td><td><code>-rtc base=...</code> in QEMU; informational</td></tr></tbody></table><h2 id="build-time-host" tabindex="-1">Build-time (host) <a class="header-anchor" href="#build-time-host" aria-label="Permalink to &quot;Build-time (host)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>grub-mkimage: cannot open ... unicode.pf2</code></td><td>font lives in grub-common</td><td>install it / point OC_TOOLS at a tree with <code>usr/share/grub/unicode.pf2</code></td></tr><tr><td><code>src-zip: not a git checkout</code></td><td>no git metadata</td><td>build from a clone or use <code>make dist</code></td></tr><tr><td><code>error: operand size mismatch for &#39;setc&#39;</code></td><td>pre-fix tree on new GAS</td><td>update past the u8-flag fix</td></tr><tr><td>packed-member warnings on new GCC</td><td>pre-fix tree</td><td>update (packed tag types)</td></tr><tr><td><code>embed_grub: missing /usr/usr/lib/grub...</code></td><td>pre-fix script</td><td>update (dual-layout probe)</td></tr><tr><td><code>chinese_font gz layout mismatch - regenerate ...</code></td><td>font blob vs header drift</td><td>regenerate chinese_font_data.c</td></tr><tr><td>a <code>_Static_assert</code> fired</td><td>cross-module layout contract drifted</td><td>the assert message names both sides — <a href="./error-codes.html">error-codes.md</a> §static-asserts</td></tr></tbody></table><h2 id="testing-gates" tabindex="-1">Testing gates <a class="header-anchor" href="#testing-gates" aria-label="Permalink to &quot;Testing gates&quot;">​</a></h2><ul><li>SSH E2E needs the seeded host key (the mtools recipe in <a href="./../dev/e2e-suites.html">../dev/e2e-suites.md</a>).</li><li>HTTPS E2E item 0 requires the self-signed chain to be REFUSED — if it connects, check <code>tls.insecure</code> is 0.</li><li>The regression suite needs pexpect; the SSH suite paramiko.</li><li>Flaky serial? See <a href="./silent-failures.html">silent-failures.md</a> §8 and <a href="./qemu-debugging.html">qemu-debugging.md</a> §errata.</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>If the error is...</th><th>Go to</th></tr></thead><tbody><tr><td>a numeric code or a panic banner</td><td><a href="./error-codes.html">error-codes.md</a></td></tr><tr><td>a message string from a specific subsystem</td><td><a href="./error-catalog.html">error-catalog.md</a></td></tr><tr><td>not printed at all</td><td><a href="./silent-failures.html">silent-failures.md</a></td></tr><tr><td>during boot / in OCBL / OCIRE</td><td><a href="./boot-failures.html">boot-failures.md</a></td></tr><tr><td>network-shaped</td><td><a href="./network-issues.html">network-issues.md</a></td></tr><tr><td>disk/filesystem-shaped</td><td><a href="./storage-issues.html">storage-issues.md</a></td></tr><tr><td>only in QEMU</td><td><a href="./qemu-debugging.html">qemu-debugging.md</a></td></tr><tr><td>a command you cannot find</td><td><a href="./../manual/function-dictionary.html">../manual/function-dictionary.md</a></td></tr></tbody></table>`,33)])])}const g=e(a,[["render",s]]);export{m as __pageData,g as default};
